import sys, os, tempfile
sys.path.insert(0, 'scripts')
import weekly as w

try:
    print(w.exclusion({'name': 'Foo', 'file': '/r/a/Foo.tsx', 'props': {'a': {'type': None, 'parent': None}}}))
except Exception as e:
    print('ERR type None', repr(e))

root = tempfile.mkdtemp()
files = {'x/a.tsx': "export default function Real(){}",
         'x/b.tsx': "import Real from './a'\nexport default Real",
         'x/c.tsx': "import Real from './a'\nexport default Real"}
for f, t in files.items():
    os.makedirs(os.path.dirname(os.path.join(root, f)), exist_ok=True)
    open(os.path.join(root, f), 'w').write(t)
found = {('x/a.tsx', 'real'): set()}


def comp(f, props):
    return {'name': 'Real', 'file': os.path.join(root, f),
            'props': {p: {'type': 'x', 'parent': None} for p in props}}


for order in (['x/b.tsx', 'x/c.tsx'], ['x/c.tsx', 'x/b.tsx']):
    comps = [comp(f, {'x/b.tsx': ['p1'], 'x/c.tsx': ['p2']}[f]) for f in order]
    items, st = w.reference(comps, found, root)
    print(order, [i['props'] for i in items], st['paired'])

# mispair via single-comp fallback: default export is a differently named local in a file with one other comp
files2 = {'y/a.tsx': "export default function Helper(){}", 'y/b.tsx': "import H from './a'\nexport default H"}
for f, t in files2.items():
    os.makedirs(os.path.dirname(os.path.join(root, f)), exist_ok=True)
    open(os.path.join(root, f), 'w').write(t)
found2 = {('y/a.tsx', 'other'): set()}
c = {'name': 'B', 'file': os.path.join(root, 'y/b.tsx'), 'props': {'p': {'type': 'x', 'parent': None}}}
print(w.reference([c], found2, root)[1])

